def txt(x):
    if x is None:
        return ''
    if isinstance(x, (list, tuple, set)):
        return ' '.join([txt(i) for i in x])
    if isinstance(x, dict):
        return ' '.join([txt(k) + ' ' + txt(v) for k, v in x.items()])
    return str(x).lower()

def need(tt):
    s = txt(tt)
    if 'clean' in s:
        return 'clean'
    if 'heat' in s:
        return 'heat'
    if 'cool' in s:
        return 'cool'
    if 'slice' in s:
        return 'slice'
    return ''

def hasobj(adm, word):
    for a in adm:
        if word in a:
            return True
    return False

def hook(ctx, nb):
    tt = txt(val(ctx, 'task.task_type', ''))
    target = txt(val(ctx, 'task.target_type', ''))
    dest = txt(val(ctx, 'task.destination_type', ''))
    tool = need(tt)
    if not tool:
        nb['transformed'] = True
    act = txt(val(ctx, 'action.final_action', '') or val(ctx, 'action.normalized', '') or val(ctx, 'action.raw', ''))
    obs = txt(ctx.get('observation', ''))
    inv = txt(val(ctx, 'world.inventory', ''))
    if target and tool and act.startswith(tool + ' ') and target in act and 'nothing happens' not in obs:
        nb['transformed'] = True
    if target and dest and act.startswith('put ') and target in act and dest in act and 'you put' in obs:
        pc = val(ctx, 'world.placed_count', 0)
        if isinstance(pc, int) and pc > nb.get('placed_count', 0):
            nb['placed_count'] = pc
        nb['last_put_step'] = val(ctx, 'step', 0) or 0
    wrong_inv = bool(target) and inv and 'not carrying' not in inv and target not in inv
    if wrong_inv:
        stage = 'wrong_inventory'
    elif target and act.startswith('put ') and target in act and 'you put' in obs and (not dest or dest in act):
        stage = 'done'
    elif target and tool and target in inv and not nb.get('transformed') and tool in act:
        stage = 'transform'
    elif target and target in inv:
        stage = 'go_destination'
    elif target and hasobj(ctx.get('admissible', []), 'take ' + target + ' '):
        stage = 'take_target'
    else:
        stage = 'find_target'
    nb['stage'] = stage
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = tt
    nb['transform_tool'] = tool
    return None

