def num(x):
    if isinstance(x, int) or isinstance(x, float):
        return x
    s = str(x)
    if s.isdigit():
        return int(s)
    return 0

def hook(ctx, nb):
    target = nb.get('target_type') or txt(val(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or txt(val(ctx, 'task.destination_type', ''))
    tool = nb.get('transform_tool') or txt(val(ctx, 'task.task_type', ''))
    stage = nb.get('stage') or 'find_target'
    if not target:
        return None
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'You appear to be carrying a non-target object. Do not place it at the destination; recover and find the requested ' + target + ' instead.'
    elif stage == 'take_target' and target in txt(val(ctx, 'world.inventory', '')):
        msg = 'A ' + target + ' is available here; take the target object rather than a distractor.'
    elif stage == 'transform':
        verb = tool
        if not verb:
            verb = 'transform'
        place = 'use the required tool'
        if verb == 'clean':
            place = 'a sinkbasin'
        if verb == 'heat':
            place = 'a microwave'
        if verb == 'cool':
            place = 'a fridge'
        if verb == 'slice':
            place = 'a knife'
        msg = 'Before placing, ' + verb + ' the ' + target + ' at ' + place + '.'
    elif stage == 'go_destination':
        msg = 'Now carry the ' + target + ' to the ' + dest + ' and use the admissible put action there.'
    elif stage == 'put_target':
        msg = 'Put the ' + target + ' in/on the ' + dest + ', not on a different receptacle.'
    if not msg or msg == nb.get('last_hint'):
        return None
    pc = num(val(ctx, 'world.placed_count', 0))
    if pc > 0 and stage in ['find_target', 'take_target'] and 'pick_two' in txt(val(ctx, 'task.task_type', '')):
        msg = 'One target is already placed; do not take it back. Find another ' + target + ' and use the same ' + dest + ' destination.'
    if msg:
        nb['last_hint'] = msg
        return {'message': msg}
    return None

