def hook(ctx, nb):
    target = txt(val(ctx, 'task.target_type', nb.get('target_type', '')))
    dest = txt(val(ctx, 'task.destination_type', nb.get('destination_type', '')))
    tool = need(val(ctx, 'task.task_type', nb.get('task_type', '')))
    tt = txt(val(ctx, 'task.task_type', ''))
    act = txt(val(ctx, 'action.final_action', '') or val(ctx, 'action.normalized', '') or val(ctx, 'action.raw', ''))
    if not target or not act:
        return None
    inv = txt(val(ctx, 'world.inventory', ''))
    wrong = bool(target) and inv and 'not carrying' not in inv and target not in inv
    if wrong and act.startswith('put ') and dest and dest in act and 'you put' not in act:
        return {'kind': 'block_and_prompt', 'message': 'This is not the requested target type. Do not place a distractor object at the destination; find the ' + target + ' instead.'}
    ad = ctx.get('admissible', [])
    take_avail = False
    trans_avail = False
    for a in ad:
        al = txt(a)
        if al.startswith('take ') and target in al and ' from ' in al and 'you take' not in al:
            take_avail = True
        if target in al and tool and al.startswith(tool + ' ') and 'nothing happens' not in al:
            trans_avail = True
    if take_avail and not wrong and not (act.startswith('take ') and target in act and 'you take' in act) and nb.get('stage') not in ['transform', 'go_destination', 'put_target', 'done']:
        return {'kind': 'block_and_prompt', 'message': 'A requested target object is available here. Take the ' + target + ' instead of continuing to search or moving away.'}
    if tool and target in inv and not nb.get('transformed') and trans_avail and not act.startswith(tool + ' ') and (act.startswith('put ') or act.startswith('examine ') or act.startswith('go ') or act == 'look' or act == 'inventory'):
        return {'kind': 'block_and_prompt', 'message': 'The required ' + tool + ' action is already admissible for the target. Do that transform before placing or examining.'}
    return None
